
(function(){
  const COLLIE_SABLE_AVATAR="data:image/webp;base64,";
  const COLLIE_TRICOLOR_AVATAR="data:image/webp;base64,";
  const NATIVE_WHITE_AVATAR="data:image/webp;base64,";
  const NATIVE_BLACK_AVATAR="data:image/webp;base64,";
  const NATIVE_FLOWER_AVATAR="data:image/webp;base64,";
  const NATIVE_YELLOW_AVATAR="data:image/webp;base64,";
  const LABRADOR_BROWN_AVATAR="data:image/webp;base64,";
  const LABRADOR_BLACK_AVATAR="data:image/webp;base64,";
  const COLLIE_BLUE_MERLE_AVATAR="data:image/webp;base64,";
  const ALASKAN_BLACK_AVATAR="data:image/webp;base64,";
  const ALASKAN_RED_AVATAR="data:image/webp;base64,";
  const ALASKAN_GRAY_AVATAR="data:image/webp;base64,";
  const OLD_ENGLISH_BLACK_WHITE_AVATAR="data:image/webp;base64,";

  const byKey=(key)=>breedCatalog.find((item)=>item.key===key);

  const collie=byKey('rough-collie');
  if(collie){
    collie.colors=['雕色','三色','蓝陨石'];
    collie.avatar=COLLIE_SABLE_AVATAR;
    collie.avatarByColor={'雕色':COLLIE_SABLE_AVATAR,'三色':COLLIE_TRICOLOR_AVATAR,'蓝陨石':COLLIE_BLUE_MERLE_AVATAR};
  }

  const nativeDog=byKey('native-medium');
  if(nativeDog){
    nativeDog.aliases=Array.from(new Set(['中华田园犬','田园犬','土狗'].concat(nativeDog.aliases||[])));
    const previous=Object.assign({},nativeDog.avatarByColor||{});
    delete previous['花'];
    delete previous['花狗'];
    nativeDog.colors=['黄','黑','白','黄白','红棕'];
    nativeDog.avatar=NATIVE_YELLOW_AVATAR;
    nativeDog.avatarByColor=Object.assign(previous,{
      '黄':NATIVE_YELLOW_AVATAR,
      '黑':NATIVE_BLACK_AVATAR,
      '白':NATIVE_WHITE_AVATAR,
      '黄白':NATIVE_FLOWER_AVATAR
    });
    const nativeIndex=breedCatalog.indexOf(nativeDog);
    if(nativeIndex>0){
      breedCatalog.splice(nativeIndex,1);
      breedCatalog.unshift(nativeDog);
    }
  }

  const labrador=byKey('labrador');
  if(labrador){
    const previous=Object.assign({},labrador.avatarByColor||{});
    labrador.colors=['奶黄色','棕色','黑色'];
    labrador.avatarByColor=Object.assign(previous,{
      '棕色':LABRADOR_BROWN_AVATAR,
      '黑色':LABRADOR_BLACK_AVATAR
    });
  }

  const golden=byKey('golden-retriever');
  if(golden){
    const deepGoldenAvatar=(golden.avatarByColor||{})['深金']||golden.avatar;
    golden.colors=['浅金'];
    golden.avatar=deepGoldenAvatar;
    golden.avatarByColor={'浅金':deepGoldenAvatar};
  }

  const alaskan=byKey('alaskan-malamute');
  if(alaskan){
    alaskan.colors=['黑色','红色','灰色'];
    alaskan.avatar=ALASKAN_BLACK_AVATAR;
    alaskan.avatarByColor={
      '黑色':ALASKAN_BLACK_AVATAR,
      '红色':ALASKAN_RED_AVATAR,
      '灰色':ALASKAN_GRAY_AVATAR
    };
  }

  const oldEnglish=byKey('old-english-sheepdog');
  if(oldEnglish){
    oldEnglish.avatar=OLD_ENGLISH_BLACK_WHITE_AVATAR;
    oldEnglish.avatarByColor=Object.assign({},oldEnglish.avatarByColor||{},
      {'黑白':OLD_ENGLISH_BLACK_WHITE_AVATAR});
  }

  const akita=byKey('akita');
  if(akita){
    akita.avatarByColor=Object.assign({},akita.avatarByColor||{},
      {'黑白':ALT_AKITA_3,'白':ALT_AKITA_2});
  }

  if(typeof coatSwatches==='object' && coatSwatches){
    delete coatSwatches['花狗'];
    coatSwatches['蓝陨石']='conic-gradient(#222 0 38%,#929da2 39% 72%,#fff 73%)';
    coatSwatches['红色']='#c7471e';
  }
  if(state.selectedBreedKey==='native-medium' && (state.selectedBreedColor==='花'||state.selectedBreedColor==='花狗')){
    state.selectedBreedColor='黄白';
  }
  if(state.selectedBreedKey==='golden-retriever' && state.selectedBreedColor==='深金'){
    state.selectedBreedColor='浅金';
  }

  const previousRenderBoard=renderBoard;
  renderBoard=function(){
    previousRenderBoard.apply(this,arguments);
    const host=arguments[0];
    const side=arguments[1];
    if(!host || side!=='front') return;
    const img=host.querySelector('.board-dog');
    if(img){
      if(state.selectedBreedKey==='rough-collie'){
        img.classList.add('board-dog-rough-collie');
        if(state.selectedColor==='三色') img.classList.add('board-dog-rough-collie-tricolor');
        if(state.selectedColor==='蓝陨石') img.classList.add('board-dog-rough-collie-blue-merle');
      }
      if(state.selectedBreedKey==='native-medium') img.classList.add('board-dog-native-tuned');
      if(state.selectedBreedKey==='labrador') img.classList.add('board-dog-labrador-safe');
      if(state.selectedBreedKey==='alaskan-malamute') img.classList.add('board-dog-new-extreme');
      if(state.selectedBreedKey==='basset' && state.selectedColor==='白黑') img.classList.add('board-dog-basset-whiteblack');
      if(state.selectedBreedKey==='cavalier' && state.selectedColor==='黑棕白') img.classList.add('board-dog-cavalier-blacktanwhite');
    }
  };

  if(typeof renderAll==='function') renderAll();
})();
